catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
		if(!newValue){
         g_form.clearOptions("certificate_name");
		}
        return;
    }
	g_form.clearOptions("certificate_name");
    var issued_by = g_form.getValue('issued_by');
    if (issued_by) {
        var cert = new GlideAjax("x_1324635_grc_ops.GRCOpsUtilsAjax");
        cert.addParam('sysparm_name', 'addCertificationOptions');
        cert.addParam('sysparm_data', issued_by);
        cert.getXMLAnswer(function(response) {
            if (response) {
                response = JSON.parse(response);
                for (var i = 0; i < response.length; i++) {
                    g_form.addOption("certificate_name", response[i], response[i]);
                }
            } else {
                g_form.addErrorMessage("There is some issue. please check.");
            }
        });
    }
    //Type appropriate comment here, and begin script below

}
